#include <vector>

std::vector<double> high_water(const std::vector<double>& pnl) {
    std::vector<double> out;
    out.reserve(pnl.size());
    for (std::size_t i = 0; i < pnl.size(); ++i)
        out.push_back(i == 0 || pnl[i] > out.back() ? pnl[i] : out.back());
    return out;
}

