#include <vector>

std::vector<double> high_water(const std::vector<double>& pnl) {
    std::vector<double> out;
    if (pnl.empty()) return out;
    double peak = pnl[0];
    for (std::size_t i = 1; i < pnl.size(); ++i) {
        if (pnl[i] > peak) peak = pnl[i];
        out.push_back(peak);
    }
    return out;
}
